-- Importazione catalogo incantesimi 2014
-- Generato da incantesimi_5e_spellbook_580_dettagli_it_metri.json. Record: 525.
-- Prerequisiti: admin_shared_catalog_rls.sql e extend_shared_spells_spellbook_import.sql.
-- scrapeStatus e verifiedEditions/verifiedVersion sono intenzionalmente ignorati.

begin;

do $spellbook_import$
declare
  v_created_by uuid;
begin
  select user_id into v_created_by
  from public.catalog_admins
  order by created_at, user_id
  limit 1;

  if v_created_by is null then
    raise exception 'Nessun amministratore presente in public.catalog_admins.';
  end if;

  create temporary table spellbook_import_rows on commit drop as
    select source_key, rules_version, name, level, school, caster_classes, cast_time, range, duration, components, material, concentration, ritual, attack_roll, saving_throw_ability, attack_range_type, damage_die, damage_modifier, damage_type, upcast_damage_die, upcast_damage_modifier, upcast_start_level, upcast_description, description, source, source_url
    from public.shared_spells
    with no data;

  insert into spellbook_import_rows (
    source_key,
    rules_version,
    name,
    level,
    school,
    caster_classes,
    cast_time,
    range,
    duration,
    components,
    material,
    concentration,
    ritual,
    attack_roll,
    saving_throw_ability,
    attack_range_type,
    damage_die,
    damage_modifier,
    damage_type,
    upcast_damage_die,
    upcast_damage_modifier,
    upcast_start_level,
    upcast_description,
    description,
    source,
    source_url
  )
  values
    ('abi-dalzim''s-horrid-wilting', '2014', 'L''orrendo appassimento di Abi-Dalzim', 8, 'necromanzia', array['stregone', 'mago']::text[], 'Azione', '45 metri', 'Istantanea', 'V, S, M', 'un po’ di spugna', false, false, false, 'con', null, '12d8', null, 'necrotico', null, null, null, null, 'Estrai l’umidità da ogni creatura presente in un cubo di 9 metri di lato con centro in un punto a tua scelta entro il raggio d’azione. Ogni creatura in quell’area deve effettuare un tiro salvezza di Costituzione. I costrutti e i non morti non ne sono influenzati, mentre le piante e gli elementali dell’acqua effettuano questo tiro salvezza con svantaggio. Una creatura subisce 12d8 danni necrotici in caso di tiro salvezza fallito, oppure la metà dei danni in caso di tiro salvezza riuscito.

Le piante non magiche presenti nell’area che non sono creature, come alberi e arbusti, appassiscono e muoiono all’istante.', 'Xanathar''s Guide to Everything', 'https://5e-spellbook.app/spells/abi-dalzim%27s-horrid-wilting'),
    ('absorb-elements', '2014', 'Assorbire gli elementi', 1, 'abiurazione', array['artefice', 'druido', 'ranger', 'stregone', 'mago']::text[], 'Reazione', 'Personale', '1 round', 'S', null, false, false, false, null, null, null, null, null, '1d6', null, 2, 'Utilizzo di uno slot incantesimo di livello superiore. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 2° livello o superiore, il danno aggiuntivo aumenta di 1d6 per ogni livello dello slot superiore al 1°.', 'L''incantesimo cattura parte dell''energia in arrivo, attenuandone l''effetto su di te e immagazzinandola per il tuo prossimo attacco in mischia. Hai resistenza al tipo di danno che ha attivato l’incantesimo fino all’inizio del tuo prossimo turno. Inoltre, la prima volta che colpisci con un attacco in mischia nel tuo prossimo turno, il bersaglio subisce 1d6 danni aggiuntivi del tipo che ha attivato l’incantesimo, dopodiché l’incantesimo termina.

Utilizzo di uno slot incantesimo di livello superiore. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 2° livello o superiore, il danno aggiuntivo aumenta di 1d6 per ogni livello dello slot superiore al 1°.', 'Xanathar’s Guide to Everything', 'https://5e-spellbook.app/spells/absorb-elements'),
    ('acid-splash', '2014', 'Spruzzo di acido', 0, 'evocazione', array['artefice', 'stregone', 'mago']::text[], 'Azione', '18 metri', 'Istantanea', 'V, S', null, false, false, false, 'dex', null, '1d6', null, 'acido', null, null, null, 'Potenziamento del trucchetto. Il danno di questo incantesimo aumenta di 1d6 quando raggiungi il 5° livello (2d6), l’11° livello (3d6) e il 17° livello (4d6).', 'Lanci una bolla di acido. Scegli una creatura che puoi vedere entro il raggio d''azione, oppure scegli due creature che puoi vedere entro il raggio d''azione e che si trovano a una distanza massima di 1,5 metri l''una dall''altra. Il bersaglio deve superare un tiro salvezza di Destrezza o subire 1d6 danni da acido.

Potenziamento del trucchetto. Il danno di questo incantesimo aumenta di 1d6 quando raggiungi il 5° livello (2d6), l’11° livello (3d6) e il 17° livello (4d6).', 'Manuale del Giocatore (2014)', 'https://5e-spellbook.app/spells/acid-splash'),
    ('aganazzar''s-scorcher', '2014', 'Lo Scorcher di Aganazzar', 2, 'invocazione', array['stregone', 'mago']::text[], 'Azione', '9 metri', 'Istantanea', 'V, S, M', 'una scaglia di drago rosso', false, false, false, 'dex', null, '3d8', null, 'fuoco', '1d8', null, 3, 'Utilizzo di uno slot incantesimo di livello superiore. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 3° livello o superiore, il danno aumenta di 1d8 per ogni livello dello slot superiore al 2°.', 'Una linea di fiamme ruggenti lunga 9 metri e larga 1,5 metri si sprigiona da te nella direzione che scegli. Ogni creatura che si trova sulla linea deve effettuare un tiro salvezza di Destrezza. Una creatura subisce 3d8 danni da fuoco in caso di tiro salvezza fallito, oppure la metà dei danni in caso di tiro salvezza riuscito.

Utilizzo di uno slot incantesimo di livello superiore. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 3° livello o superiore, il danno aumenta di 1d8 per ogni livello dello slot superiore al 2°.', 'Xanathar''s Guide to Everything', 'https://5e-spellbook.app/spells/aganazzar%27s-scorcher'),
    ('aid', '2014', 'Aiuto', 2, 'abiurazione', array['artefice', 'bardo', 'chierico', 'paladino', 'ranger']::text[], 'Azione', '9 metri', '8 ore', 'V, S, M', 'una minuscola striscia di stoffa bianca', false, false, false, null, null, null, null, null, null, null, null, 'Utilizzo di uno slot incantesimo di livello superiore. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 3° livello o superiore, i punti ferita del bersaglio aumentano di ulteriori 5 per ogni livello dello slot superiore al 2°.', 'Il tuo incantesimo rafforza i tuoi alleati con tenacia e determinazione. Scegli fino a tre creature entro il raggio d''azione. Il massimo dei punti ferita e i punti ferita attuali di ciascun bersaglio aumentano di 5 per tutta la durata dell''incantesimo.

Utilizzo di uno slot incantesimo di livello superiore. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 3° livello o superiore, i punti ferita del bersaglio aumentano di ulteriori 5 per ogni livello dello slot superiore al 2°.', 'Manuale del Giocatore (2014)', 'https://5e-spellbook.app/spells/aid'),
    ('air-bubble', '2014', 'Bolla d''aria', 2, 'evocazione', array['artefice', 'druido', 'ranger', 'stregone', 'mago']::text[], 'Azione', '18 metri', '24 ore', 'S', null, false, false, false, null, null, null, null, null, null, null, null, 'Utilizzo di uno slot incantesimo di livello superiore. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 3° livello o superiore, puoi creare due sfere di aria fresca aggiuntive per ogni livello dello slot superiore al 2°.', 'Crei una sfera spettrale attorno alla testa di una creatura consenziente che puoi vedere entro il raggio d''azione. Il globo è pieno d’aria fresca che dura fino al termine dell’incantesimo. Se la creatura ha più di una testa, il globo d’aria appare attorno a una sola delle sue teste (il che è sufficiente affinché la creatura eviti il soffocamento, supponendo che tutte le sue teste condividano lo stesso apparato respiratorio).

Utilizzo di uno slot incantesimo di livello superiore. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 3° livello o superiore, puoi creare due sfere di aria fresca aggiuntive per ogni livello dello slot superiore al 2°.', 'Astral Adventurer''s Guide', 'https://5e-spellbook.app/spells/air-bubble'),
    ('alarm', '2014', 'Allarme', 1, 'abiurazione', array['artefice', 'ranger', 'mago']::text[], '1 minuto o Rituale', '9 metri', '8 ore', 'V, S, M', 'una campanella e un pezzo di filo d''argento sottile', false, true, false, null, null, null, null, null, null, null, null, null, 'Si imposta un allarme contro le intrusioni indesiderate. Scegli una porta, una finestra o un’area entro il raggio d’azione che non sia più grande di un cubo di 6 metri. Fino al termine dell’incantesimo, un allarme ti avvisa ogni volta che una creatura di taglia Minuscola o superiore tocca o entra nell’area protetta. Quando lanci l’incantesimo, puoi designare le creature che non faranno scattare l’allarme. Puoi anche scegliere se l’allarme sia mentale o acustico.

Un allarme mentale ti avvisa con un segnale nella tua mente se ti trovi entro 1 miglio dall’area protetta. Questo segnale ti sveglia se stai dormendo.

Un allarme acustico produce il suono di una campanella per 10 secondi entro 18 metri.', 'Manuale del Giocatore (2014)', 'https://5e-spellbook.app/spells/alarm'),
    ('alter-incantatore', '2014', 'Alter Incantatore', 2, 'trasmutazione', array['artefice', 'stregone', 'mago']::text[], 'Azione', 'Personale', 'Concentrazione, 1 ora', 'V, S', null, true, false, false, null, null, null, null, null, null, null, null, null, 'Assumi una forma diversa. Quando lanci l’incantesimo, scegli una delle seguenti opzioni, i cui effetti durano per tutta la durata dell’incantesimo. Finché l’incantesimo dura, puoi terminare un’opzione come azione per ottenere i benefici di un’altra.

Adattamento acquatico. Adatti il tuo corpo a un ambiente acquatico, sviluppando branchie e membrane tra le dita. Puoi respirare sott’acqua e ottieni una velocità di nuoto pari alla tua velocità di marcia.

Cambiamento di aspetto. Trasformi il tuo aspetto. Decidi tu come apparire, compresi altezza, peso, tratti del viso, timbro della voce, lunghezza dei capelli, colore e caratteristiche distintive, se presenti. Puoi farti apparire come un membro di un’altra razza, anche se nessuna delle tue statistiche cambia. Inoltre, non puoi assumere le sembianze di una creatura di dimensioni diverse dalle tue e la tua forma di base rimane la stessa; se sei bipede, ad esempio, non puoi usare questo incantesimo per diventare quadrupede. In qualsiasi momento durante la durata dell’incantesimo, puoi usare la tua azione per cambiare nuovamente il tuo aspetto in questo modo.

Armi naturali. Ti crescono artigli, zanne, spine, corna o un’altra arma naturale a tua scelta. I tuoi attacchi a mani nude infliggono 1d6 danni da contusione, da perforazione o da taglio, a seconda dell’arma naturale che hai scelto, e sei competente negli attacchi a mani nude. Infine, l’arma naturale è magica e ottieni un bonus di +1 ai tiri per colpire e ai tiri per il danno che effettui usandola.', 'Manuale del Giocatore (2014)', 'https://5e-spellbook.app/spells/alter-Incantatore'),
    ('animal-friendship', '2014', 'Amicizia con gli animali', 1, 'ammaliamento', array['bardo', 'druido', 'ranger']::text[], 'Azione', '9 metri', '24 ore', 'V, S, M', 'un boccone di cibo', false, false, false, 'wis', null, null, null, null, null, null, null, 'Utilizzo di uno slot incantesimo di livello superiore. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 2° livello o superiore, puoi influenzare una bestia aggiuntiva per ogni livello dello slot superiore al 1°.', 'Questo incantesimo ti permette di convincere una bestia che non intendi farle del male. Scegli una bestia che puoi vedere entro il raggio d''azione. La bestia deve vederti e sentirti. Se l''Intelligenza della bestia è pari o superiore a 4, l''incantesimo fallisce. Altrimenti, la bestia deve superare un tiro salvezza di Saggezza o rimanere incantata da te per tutta la durata dell''incantesimo. Se tu o uno dei tuoi compagni infligge un danno al bersaglio, l’incantesimo termina.

Utilizzo di uno slot incantesimo di livello superiore. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 2° livello o superiore, puoi influenzare una bestia aggiuntiva per ogni livello dello slot superiore al 1°.', 'Manuale del Giocatore (2014)', 'https://5e-spellbook.app/spells/animal-friendship'),
    ('animal-messenger', '2014', 'Messaggero animale', 2, 'ammaliamento', array['bardo', 'druido', 'ranger']::text[], 'Azione o Rituale', '9 metri', '24 ore', 'V, S, M', 'un boccone di cibo', false, true, false, null, null, null, null, null, null, null, null, 'Utilizzo di uno slot incantesimo di livello superiore. Se lanci questo incantesimo utilizzando uno slot incantesimo di 3° livello o superiore, la durata dell’incantesimo aumenta di 48 ore per ogni livello dello slot superiore al 2°.', 'Grazie a questo incantesimo, puoi utilizzare un animale per consegnare un messaggio. Scegli una bestia Minuscola che puoi vedere entro il raggio d’azione, come uno scoiattolo, una ghiandaia blu o un pipistrello. Devi specificare un luogo, che devi aver visitato, e un destinatario che corrisponda a una descrizione generica, come «un uomo o una donna che indossa l’uniforme della guardia cittadina» o «un nano dai capelli rossi che indossa un cappello a punta». Devi inoltre pronunciare un messaggio di massimo venticinque parole. L’animale bersaglio viaggia per tutta la durata dell’incantesimo verso il luogo specificato, percorrendo circa 50 miglia ogni 24 ore se si tratta di un messaggero volante, oppure 25 miglia per gli altri animali.

Quando il messaggero arriva, consegna il tuo messaggio alla creatura che hai descritto, riproducendo il suono della tua voce. Il messaggero parla solo con una creatura che corrisponda alla descrizione che hai fornito. Se il messaggero non raggiunge la sua destinazione prima che l’incantesimo finisca, il messaggio va perso e la bestia torna al luogo in cui hai lanciato l’incantesimo.

Utilizzo di uno slot incantesimo di livello superiore. Se lanci questo incantesimo utilizzando uno slot incantesimo di 3° livello o superiore, la durata dell’incantesimo aumenta di 48 ore per ogni livello dello slot superiore al 2°.', 'Manuale del Giocatore (2014)', 'https://5e-spellbook.app/spells/animal-messenger'),
    ('animal-shapes', '2014', 'Forme animali', 8, 'trasmutazione', array['druido']::text[], 'Azione', '9 metri', 'Concentrazione, 24 ore', 'V, S', null, true, false, false, null, null, null, null, null, null, null, null, null, 'La tua magia trasforma gli altri in bestie. Scegli un numero qualsiasi di creature consenzienti che puoi vedere entro il raggio d''azione. Trasformi ciascun bersaglio nella forma di una bestia di taglia Grande o inferiore con un grado di sfida pari o inferiore a 4. Nei turni successivi, puoi usare la tua azione per trasformare le creature interessate in nuove forme.

La trasformazione dura per tutta la durata di ciascun bersaglio, oppure fino a quando il bersaglio non scende a 0 punti ferita o muore. Puoi scegliere una forma diversa per ciascun bersaglio. Le statistiche di gioco di un bersaglio vengono sostituite da quelle della bestia scelta, sebbene il bersaglio mantenga il proprio allineamento e i propri punteggi di Intelligenza, Saggezza e Carisma. Il bersaglio assume i punti ferita della sua nuova forma e, quando ritorna alla sua forma normale, riprende il numero di punti ferita che aveva prima della trasformazione. Se ritorna alla forma normale a seguito di una riduzione a 0 punti ferita, qualsiasi danno in eccesso viene trasferito alla sua forma normale. Finché il danno in eccesso non riduce la forma normale della creatura a 0 punti ferita, essa non viene messa fuori combattimento. La creatura è limitata nelle azioni che può compiere dalla natura della sua nuova forma e non può parlare né lanciare incantesimi.

L’equipaggiamento del bersaglio si fonde con la nuova forma. Il bersaglio non può attivare, brandire o trarre alcun beneficio dal proprio equipaggiamento.', 'Manuale del Giocatore (2014)', 'https://5e-spellbook.app/spells/animal-shapes'),
    ('animate-dead', '2014', 'Morti viventi', 3, 'necromanzia', array['chierico', 'mago']::text[], '1 minuto', '3 metri', 'Istantanea', 'V, S, M', 'una goccia di sangue, un pezzo di carne e un pizzico di polvere d’ossa', false, false, false, null, null, null, null, null, null, null, null, 'Utilizzo di uno slot incantesimo di livello superiore. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 4° livello o superiore, animi o riprendi il controllo su due creature non morte aggiuntive per ogni livello dello slot superiore al 3°. Ciascuna delle creature deve provenire da un cadavere o da un mucchio di ossa diverso.', 'Questo incantesimo crea un servitore non morto. Scegli un mucchio di ossa o il cadavere di un umanoide di taglia Media o Piccola entro il raggio d''azione. Il tuo incantesimo infonde nel bersaglio una ripugnante parvenza di vita, resuscitandolo come creatura non morta. Il bersaglio diventa uno scheletro se hai scelto le ossa o uno zombie se hai scelto un cadavere (il DM dispone delle statistiche di gioco della creatura).

In ciascuno dei tuoi turni, puoi usare un''azione bonus per comandare mentalmente qualsiasi creatura che hai creato con questo incantesimo, purché si trovi entro 18 metri da te (se controlli più creature, puoi comandarne una o tutte contemporaneamente, impartendo lo stesso comando a ciascuna di esse). Decidi tu quale azione compirà la creatura e dove si sposterà durante il suo prossimo turno, oppure puoi impartire un comando generale, come ad esempio sorvegliare una determinata stanza o un corridoio. Se non impartisci alcun comando, la creatura si limita a difendersi dalle creature ostili. Una volta ricevuto un ordine, la creatura continua a seguirlo fino al completamento del compito.

La creatura rimane sotto il tuo controllo per 24 ore, dopodiché smette di obbedire a qualsiasi comando tu le abbia impartito. Per mantenere il controllo sulla creatura per altre 24 ore, devi lanciare nuovamente questo incantesimo sulla creatura prima che il periodo di 24 ore in corso finisca. Questo uso dell’incantesimo riafferma il tuo controllo su un massimo di quattro creature che hai animato con questo incantesimo, anziché animarne una nuova.

Utilizzo di uno slot incantesimo di livello superiore. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 4° livello o superiore, animi o riprendi il controllo su due creature non morte aggiuntive per ogni livello dello slot superiore al 3°. Ciascuna delle creature deve provenire da un cadavere o da un mucchio di ossa diverso.', 'Manuale del Giocatore (2014)', 'https://5e-spellbook.app/spells/animate-dead'),
    ('animate-objects', '2014', 'Oggetti animati', 5, 'trasmutazione', array['artefice', 'bardo', 'stregone', 'mago']::text[], 'Azione', '36 metri', 'Concentrazione, 1 minuto', 'V, S', null, true, false, false, null, null, null, null, null, null, null, null, 'Utilizzo di uno slot incantesimo di livello superiore. Se lanci questo incantesimo utilizzando uno slot incantesimo di 6° livello o superiore, puoi animare due oggetti aggiuntivi per ogni livello dello slot superiore al 5°.', 'Gli oggetti prendono vita al tuo comando. Scegli fino a dieci oggetti non magici entro il raggio d’azione che non siano indossati o trasportati. I bersagli medi contano come due oggetti, quelli grandi come quattro oggetti, quelli enormi come otto oggetti. Non puoi animare alcun oggetto più grande di uno enorme. Ogni bersaglio prende vita e diventa una creatura sotto il tuo controllo fino al termine dell’incantesimo o fino a quando i suoi punti ferita non scendono a 0.

Come azione bonus, puoi impartire un comando mentale a qualsiasi creatura che hai creato con questo incantesimo, purché si trovi entro 150 metri da te (se controlli più creature, puoi comandarne una o tutte contemporaneamente, impartendo lo stesso comando a ciascuna di esse). Decidi quale azione compirà la creatura e dove si sposterà durante il suo prossimo turno, oppure puoi impartire un comando generale, come ad esempio sorvegliare una determinata sala o un corridoio. Se non impartisci alcun comando, la creatura si limita a difendersi dalle creature ostili. Una volta ricevuto un ordine, la creatura continua a seguirlo fino al completamento del compito.

